//! Unit tests for the key-derivation wrappers.
//!
//! The `bcrypt-pbkdf` known answers are the golden vectors from the Go
//! project's independent implementation of the same OpenBSD construction,
//! which were themselves generated by the OpenBSD reference. The third
//! covers a non-ASCII passphrase and an output spanning three blocks, so
//! the stride transposition at the end of the construction is exercised
//! rather than assumed.
//!
//! The PBKDF2-HMAC-SHA1 answers are RFC 6070's and RFC 3962 Appendix B's;
//! the counter-mode answers are RFC 8009 Appendix A's, and the multi-block
//! and SMB 3 answers come from `cryptography`'s independent `KBKDFHMAC`.

use super::{
    bcrypt_pbkdf, bcrypt_pbkdf_scratch_len, derive_key, kdf_counter_sha256, kdf_counter_sha384,
    pbkdf2_sha1, pbkdf2_sha256, pbkdf2_sha256_verify, BcryptPbkdfError, KdfLengthError,
    BCRYPT_PBKDF_MAX_OUTPUT_LEN, DERIVED_KEY_LEN,
};
use crate::test_hex::hex;

use core::num::NonZeroU32;

/// Golden vector 1: 12 rounds, 8-byte passphrase,
/// 4-byte salt, 32-byte output.
const V0_ROUNDS: u32 = 12;
const V0_PASSPHRASE: [u8; 8] = [0x70, 0x61, 0x73, 0x73, 0x77, 0x6f, 0x72, 0x64];
const V0_SALT: [u8; 4] = [0x73, 0x61, 0x6c, 0x74];
const V0_EXPECTED: [u8; 32] = [
    0x1a, 0xe4, 0x2c, 0x05, 0xd4, 0x87, 0xbc, 0x02, 0xf6, 0x49, 0x21, 0xa4, 0xeb, 0xe4, 0xea, 0x93,
    0xbc, 0xac, 0xfe, 0x13, 0x5f, 0xda, 0x99, 0x97, 0x4c, 0x06, 0xb7, 0xb0, 0x1f, 0xae, 0x14, 0x9a,
];

/// Golden vector 2: 3 rounds, 19-byte passphrase,
/// 11-byte salt, 32-byte output.
const V1_ROUNDS: u32 = 3;
const V1_PASSPHRASE: [u8; 19] = [
    0x70, 0x61, 0x73, 0x73, 0x77, 0x6f, 0x72, 0x64, 0x79, 0x00, 0x50, 0x41, 0x53, 0x53, 0x57, 0x4f,
    0x52, 0x44, 0x00,
];
const V1_SALT: [u8; 11] = [
    0x73, 0x61, 0x6c, 0x74, 0x79, 0x00, 0x53, 0x41, 0x4c, 0x54, 0x00,
];
const V1_EXPECTED: [u8; 32] = [
    0x7f, 0x31, 0x0b, 0xd3, 0xe7, 0x8c, 0x32, 0x80, 0xc5, 0x9c, 0xe4, 0x59, 0x52, 0x11, 0xa2, 0x92,
    0x8e, 0x8d, 0x4e, 0xc7, 0x44, 0xc1, 0xed, 0x2e, 0xfc, 0x9f, 0x76, 0x4e, 0x33, 0x88, 0xe0, 0xad,
];

/// Golden vector 3: 8 rounds, 29-byte passphrase,
/// 33-byte salt, 88-byte output.
const V2_ROUNDS: u32 = 8;
const V2_PASSPHRASE: [u8; 29] = [
    0xd1, 0x81, 0xd0, 0xb5, 0xd0, 0xba, 0xd1, 0x80, 0xd0, 0xb5, 0xd1, 0x82, 0xd0, 0xbd, 0xd0, 0xbe,
    0xd0, 0xb5, 0x20, 0xd1, 0x81, 0xd0, 0xbb, 0xd0, 0xbe, 0xd0, 0xb2, 0xd0, 0xbe,
];
const V2_SALT: [u8; 33] = [
    0xd0, 0xbf, 0xd0, 0xbe, 0xd1, 0x81, 0xd0, 0xbe, 0xd0, 0xbb, 0xd0, 0xb8, 0xd1, 0x82, 0xd1, 0x8c,
    0x20, 0xd0, 0xbd, 0xd0, 0xb5, 0xd0, 0xbc, 0xd0, 0xbd, 0xd0, 0xbe, 0xd0, 0xb6, 0xd0, 0xba, 0xd0,
    0xbe,
];
const V2_EXPECTED: [u8; 88] = [
    0x8d, 0xf4, 0x3f, 0xc6, 0xfe, 0x13, 0x1f, 0xc4, 0x7f, 0x0c, 0x9e, 0x39, 0x22, 0x4b, 0xd9, 0x4c,
    0x70, 0xb6, 0xfc, 0xc8, 0xee, 0x81, 0x35, 0xfa, 0xdd, 0xf6, 0x11, 0x56, 0xe6, 0xcb, 0x27, 0x33,
    0xea, 0x76, 0x5f, 0x31, 0x5a, 0x3e, 0x1e, 0x4a, 0xfc, 0x35, 0xbf, 0x86, 0x87, 0xd1, 0x89, 0x25,
    0x4c, 0x1e, 0x05, 0xa6, 0xfe, 0x80, 0xc0, 0x61, 0x7f, 0x91, 0x83, 0xd6, 0x72, 0x60, 0xd6, 0xa1,
    0x15, 0xc6, 0xc9, 0x4e, 0x36, 0x03, 0xe2, 0x30, 0x3f, 0xbb, 0x43, 0xa7, 0x6a, 0x64, 0x52, 0x3f,
    0xfd, 0xa6, 0x86, 0xb1, 0xd4, 0x51, 0x85, 0x43,
];

#[test]
fn bcrypt_pbkdf_matches_the_reference_vectors() {
    let mut out = [0u8; 32];
    let mut scratch = [0u8; bcrypt_pbkdf_scratch_len(32)];
    bcrypt_pbkdf(&V0_PASSPHRASE, &V0_SALT, V0_ROUNDS, &mut out, &mut scratch)
        .expect("vector 0 derives");
    assert_eq!(out, V0_EXPECTED, "vector 0");

    let mut out = [0u8; 32];
    let mut scratch = [0u8; bcrypt_pbkdf_scratch_len(32)];
    bcrypt_pbkdf(&V1_PASSPHRASE, &V1_SALT, V1_ROUNDS, &mut out, &mut scratch)
        .expect("vector 1 derives");
    assert_eq!(out, V1_EXPECTED, "vector 1");

    let mut out = [0u8; 88];
    let mut scratch = [0u8; bcrypt_pbkdf_scratch_len(88)];
    bcrypt_pbkdf(&V2_PASSPHRASE, &V2_SALT, V2_ROUNDS, &mut out, &mut scratch)
        .expect("vector 2 derives");
    assert_eq!(out, V2_EXPECTED, "vector 2");
}

#[test]
fn bcrypt_pbkdf_refuses_malformed_inputs() {
    let mut out = [0u8; 32];
    let mut scratch = [0u8; 32];

    assert_eq!(
        bcrypt_pbkdf(&[], &V0_SALT, V0_ROUNDS, &mut out, &mut scratch),
        Err(BcryptPbkdfError(())),
        "an empty passphrase"
    );
    assert_eq!(
        bcrypt_pbkdf(&V0_PASSPHRASE, &[], V0_ROUNDS, &mut out, &mut scratch),
        Err(BcryptPbkdfError(())),
        "an empty salt"
    );
    assert_eq!(
        bcrypt_pbkdf(&V0_PASSPHRASE, &V0_SALT, 0, &mut out, &mut scratch),
        Err(BcryptPbkdfError(())),
        "zero rounds"
    );
    assert_eq!(
        bcrypt_pbkdf(&V0_PASSPHRASE, &V0_SALT, V0_ROUNDS, &mut [], &mut scratch),
        Err(BcryptPbkdfError(())),
        "an empty output"
    );

    // A scratch buffer one block short is refused rather than truncating
    // the derivation.
    let mut short = [0u8; 31];
    assert_eq!(
        bcrypt_pbkdf(&V0_PASSPHRASE, &V0_SALT, V0_ROUNDS, &mut out, &mut short),
        Err(BcryptPbkdfError(())),
        "a short scratch buffer"
    );
}

#[test]
fn the_scratch_rule_rounds_up_to_the_block() {
    assert_eq!(bcrypt_pbkdf_scratch_len(0), 0);
    assert_eq!(bcrypt_pbkdf_scratch_len(1), 32);
    assert_eq!(bcrypt_pbkdf_scratch_len(32), 32);
    assert_eq!(bcrypt_pbkdf_scratch_len(33), 64);
    // The OpenSSH v1 container derives a 32-byte key plus a 16-byte IV.
    assert_eq!(bcrypt_pbkdf_scratch_len(48), 64);
    assert_eq!(
        bcrypt_pbkdf_scratch_len(BCRYPT_PBKDF_MAX_OUTPUT_LEN),
        BCRYPT_PBKDF_MAX_OUTPUT_LEN
    );
}

/// More rounds give a different key, so the cost parameter is really fed
/// into the derivation rather than ignored.
#[test]
fn the_round_count_changes_the_result() {
    let mut four = [0u8; 32];
    let mut eight = [0u8; 32];
    let mut scratch = [0u8; 32];
    bcrypt_pbkdf(&V0_PASSPHRASE, &V0_SALT, 4, &mut four, &mut scratch).expect("derives");
    bcrypt_pbkdf(&V0_PASSPHRASE, &V0_SALT, 8, &mut eight, &mut scratch).expect("derives");
    assert_ne!(four, eight);
}

const SECRET: [u8; 32] = [0x42; 32];

fn rounds(n: u32) -> NonZeroU32 {
    NonZeroU32::new(n).expect("non-zero")
}

#[test]
fn pbkdf2_matches_the_published_sha256_vectors() {
    // The de-facto standard PBKDF2-HMAC-SHA256 vectors (the SHA-256
    // re-computation of the RFC 6070 inputs, as published in the
    // RustCrypto and OpenSSL test suites).
    assert_eq!(
        pbkdf2_sha256(b"password", b"salt", rounds(1)),
        hex("120fb6cffcf8b32c43e7225256c4f837a86548c92ccc35480805987cb70be17b"),
    );
    assert_eq!(
        pbkdf2_sha256(b"password", b"salt", rounds(2)),
        hex("ae4d0c95af6b46d32d0adff928f06dd02a303f8ef3c251dfd6e2d85a95474c43"),
    );
    assert_eq!(
        pbkdf2_sha256(b"password", b"salt", rounds(4096)),
        hex("c5e478d59288c841aa530db6845c4c8d962893a001ce4e11a4963873aa98134a"),
    );
}

#[test]
fn pbkdf2_inputs_are_all_load_bearing() {
    let base = pbkdf2_sha256(b"password", b"salt", rounds(2));
    assert_ne!(pbkdf2_sha256(b"passwore", b"salt", rounds(2)), base);
    assert_ne!(pbkdf2_sha256(b"password", b"selt", rounds(2)), base);
    assert_ne!(pbkdf2_sha256(b"password", b"salt", rounds(3)), base);
}

#[test]
fn pbkdf2_verify_accepts_genuine_and_rejects_tampered_hashes() {
    let hash = pbkdf2_sha256(b"correct horse", b"battery staple", rounds(16));
    assert!(pbkdf2_sha256_verify(
        b"correct horse",
        b"battery staple",
        rounds(16),
        &hash
    ));
    assert!(!pbkdf2_sha256_verify(
        b"wrong horse",
        b"battery staple",
        rounds(16),
        &hash
    ));
    let mut bad = hash;
    bad[0] ^= 0x01;
    assert!(!pbkdf2_sha256_verify(
        b"correct horse",
        b"battery staple",
        rounds(16),
        &bad
    ));
}

#[test]
fn derivation_is_deterministic_and_full_width() {
    let a = derive_key(&SECRET, b"arxfs/content");
    let b = derive_key(&SECRET, b"arxfs/content");
    assert_eq!(a, b);
    assert_eq!(a.len(), DERIVED_KEY_LEN);
}

#[test]
fn distinct_contexts_yield_independent_keys() {
    let content = derive_key(&SECRET, b"arxfs/content");
    let filename = derive_key(&SECRET, b"arxfs/filename");
    let meta = derive_key(&SECRET, b"arxfs/meta-mac");
    assert_ne!(content, filename);
    assert_ne!(content, meta);
    assert_ne!(filename, meta);
}

#[test]
fn distinct_secrets_yield_independent_keys() {
    let other = [0x43; 32];
    assert_ne!(
        derive_key(&SECRET, b"arxfs/content"),
        derive_key(&other, b"arxfs/content")
    );
}

#[test]
fn pbkdf2_sha1_matches_rfc_6070() {
    let mut out = [0u8; 20];
    pbkdf2_sha1(b"password", b"salt", rounds(1), &mut out).expect("defined length");
    assert_eq!(out, hex("0c60c80f961f0e71f3a9b524af6012062fe037a6"));
    pbkdf2_sha1(b"password", b"salt", rounds(2), &mut out).expect("defined length");
    assert_eq!(out, hex("ea6c014dc72d6f8ccd1ed92ace1d41f0d8de8957"));
    pbkdf2_sha1(b"password", b"salt", rounds(4096), &mut out).expect("defined length");
    assert_eq!(out, hex("4b007901b765489abead49d926f721d065a429c1"));
}

#[test]
fn pbkdf2_sha1_spans_blocks_and_truncates_the_last() {
    let mut out = [0u8; 25];
    pbkdf2_sha1(
        b"passwordPASSWORDpassword",
        b"saltSALTsaltSALTsaltSALTsaltSALTsalt",
        rounds(4096),
        &mut out,
    )
    .expect("defined length");
    assert_eq!(
        out,
        hex("3d2eec4fe41c849b80c8d83662c0e44a8b291a964cf2f07038")
    );
}

#[test]
fn pbkdf2_sha1_gives_the_rfc_3962_string_to_key_intermediates() {
    let mut aes128 = [0u8; 16];
    pbkdf2_sha1(
        b"password",
        b"ATHENA.MIT.EDUraeburn",
        rounds(1),
        &mut aes128,
    )
    .expect("defined length");
    assert_eq!(aes128, hex("cdedb5281bb2f801565a1122b2563515"));
    let mut aes256 = [0u8; 32];
    pbkdf2_sha1(
        b"password",
        b"ATHENA.MIT.EDUraeburn",
        rounds(1),
        &mut aes256,
    )
    .expect("defined length");
    assert_eq!(
        aes256,
        hex("cdedb5281bb2f801565a1122b25635150ad1f7a04bb9f3a333ecc0e2e1f70837")
    );
}

#[test]
fn pbkdf2_sha1_refuses_an_empty_output() {
    assert_eq!(
        pbkdf2_sha1(b"password", b"salt", rounds(1), &mut []),
        Err(KdfLengthError(()))
    );
}

#[test]
fn the_counter_kdf_matches_rfc_8009() {
    let base = hex::<16>("3705d96080c17728a0e800eab6e0d23c");
    let mut kc = [0u8; 16];
    kdf_counter_sha256(&base, &hex::<5>("0000000299"), b"", &mut kc).expect("defined length");
    assert_eq!(kc, hex("b31a018a48f54776f403e9a396325dc3"));
    let mut ke = [0u8; 16];
    kdf_counter_sha256(&base, &hex::<5>("00000002aa"), b"", &mut ke).expect("defined length");
    assert_eq!(ke, hex("9b197dd1e8c5609d6e67c3e37c62c72e"));

    let base = hex::<32>("6d404d37faf79f9df0d33568d320669800eb4836472ea8a026d16b7182460c52");
    let mut kc = [0u8; 24];
    kdf_counter_sha384(&base, &hex::<5>("0000000299"), b"", &mut kc).expect("defined length");
    assert_eq!(kc, hex("ef5718be86cc84963d8bbb5031e9f5c4ba41f28faf69e73d"));
    let mut ke = [0u8; 32];
    kdf_counter_sha384(&base, &hex::<5>("00000002aa"), b"", &mut ke).expect("defined length");
    assert_eq!(
        ke,
        hex("56ab22bee63d82d7bc5227f6773f8ea7a5eb1c825160c38312980c442e5c7e49")
    );
}

#[test]
fn the_counter_kdf_derives_smb_3_keys_and_spans_blocks() {
    let mut signing = [0u8; 16];
    kdf_counter_sha256(
        &hex::<16>("7cd451825d0450d235424e44ba6e78cc"),
        b"SMB2AESCMAC\0",
        b"SmbSign\0",
        &mut signing,
    )
    .expect("defined length");
    assert_eq!(signing, hex("0b7e9c5cac36c0f6ea9ab275298cedce"));

    let mut long = [0u8; 48];
    kdf_counter_sha256(&[1u8; 16], b"SMB2AESCCM\0", b"ServerIn \0", &mut long)
        .expect("defined length");
    assert_eq!(
        long,
        hex(
            "72e56fa27958c89426b3257f11fc78f0abf4512e91f82e55488c22516ee3b266\
             d0c94f55b05303eef465c7e17594d492"
        )
    );
}

#[test]
fn the_counter_kdf_refuses_an_empty_output() {
    assert_eq!(
        kdf_counter_sha256(&[1u8; 16], b"label", b"", &mut []),
        Err(KdfLengthError(()))
    );
}
